const BASELINE={"policies":[{"name":"zc_datasets_read","check":null,"roles":["authenticated"],"table":"zc_datasets","using":"(zc_is_member(company_id) AND (((dataset = ANY (ARRAY['cars'::text, 'covers'::text])) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_datasets.company_id) AND m.active AND (m.role = ANY (ARRAY['admin'::text, 'accountant'::text]))))))) OR ((dataset <> ALL (ARRAY['cars'::text, 'covers'::text])) AND (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_datasets.company_id) AND m.active AND (m.role = ANY (ARRAY['admin'::text, 'accountant'::text]))))))))","schema":"public","command":"SELECT","permissive":"PERMISSIVE"},{"name":"snote_brand_storage_delete_guard","check":null,"roles":["authenticated"],"table":"objects","using":"((bucket_id <> 'zc-vehicle-private'::text) OR (split_part(name, '/'::text, 3) <> 'branding'::text) OR (EXISTS ( SELECT 1\n   FROM zc_members member\n  WHERE ((member.user_id = ( SELECT auth.uid() AS uid)) AND ((member.company_id)::text = split_part(objects.name, '/'::text, 1)) AND (member.active IS TRUE) AND (member.role = 'admin'::text)))))","schema":"storage","command":"DELETE","permissive":"RESTRICTIVE"},{"name":"snote_brand_storage_insert_guard","check":"((bucket_id <> 'zc-vehicle-private'::text) OR (split_part(name, '/'::text, 3) <> 'branding'::text) OR ((split_part(name, '/'::text, 2) = (( SELECT auth.uid() AS uid))::text) AND (EXISTS ( SELECT 1\n   FROM zc_members member\n  WHERE ((member.user_id = ( SELECT auth.uid() AS uid)) AND ((member.company_id)::text = split_part(objects.name, '/'::text, 1)) AND (member.active IS TRUE) AND (member.role = 'admin'::text))))))","roles":["authenticated"],"table":"objects","using":null,"schema":"storage","command":"INSERT","permissive":"RESTRICTIVE"},{"name":"snote_shared_vehicle_file_read","check":null,"roles":["authenticated"],"table":"objects","using":"((bucket_id = 'zc-vehicle-private'::text) AND snote_private.shared_vehicle_file(name))","schema":"storage","command":"SELECT","permissive":"PERMISSIVE"},{"name":"zc_storage_delete","check":null,"roles":["authenticated"],"table":"objects","using":"((bucket_id = 'zc-vehicle-private'::text) AND\nCASE\n    WHEN (split_part(name, '/'::text, 1) ~ '^[a-f0-9-]{36}$'::text) THEN zc_is_member((split_part(name, '/'::text, 1))::uuid)\n    ELSE false\nEND AND ((split_part(name, '/'::text, 2) = (( SELECT auth.uid() AS uid))::text) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND m.active AND (m.role = 'admin'::text) AND ((m.company_id)::text = split_part(objects.name, '/'::text, 1)))))))","schema":"storage","command":"DELETE","permissive":"PERMISSIVE"},{"name":"zc_storage_insert","check":"((bucket_id = 'zc-vehicle-private'::text) AND (split_part(name, '/'::text, 2) = (auth.uid())::text) AND zc_is_member((split_part(name, '/'::text, 1))::uuid))","roles":["authenticated"],"table":"objects","using":null,"schema":"storage","command":"INSERT","permissive":"PERMISSIVE"},{"name":"zc_storage_read","check":null,"roles":["authenticated"],"table":"objects","using":"((bucket_id = 'zc-vehicle-private'::text) AND zc_is_member((split_part(name, '/'::text, 1))::uuid))","schema":"storage","command":"SELECT","permissive":"PERMISSIVE"},{"name":"zc_customers_delete","check":null,"roles":["authenticated"],"table":"zc_customers","using":"(zc_is_member(company_id) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_customers.company_id) AND m.active AND (m.role = 'admin'::text))))))","schema":"public","command":"DELETE","permissive":"PERMISSIVE"},{"name":"zc_customers_insert","check":"(zc_is_member(company_id) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_customers.company_id) AND m.active AND (m.role = 'admin'::text))))))","roles":["authenticated"],"table":"zc_customers","using":null,"schema":"public","command":"INSERT","permissive":"PERMISSIVE"},{"name":"zc_customers_read","check":null,"roles":["authenticated"],"table":"zc_customers","using":"(zc_is_member(company_id) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_customers.company_id) AND m.active AND (m.role = 'admin'::text))))))","schema":"public","command":"SELECT","permissive":"PERMISSIVE"},{"name":"zc_customers_update","check":"(zc_is_member(company_id) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_customers.company_id) AND m.active AND (m.role = 'admin'::text))))))","roles":["authenticated"],"table":"zc_customers","using":"(zc_is_member(company_id) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_customers.company_id) AND m.active AND (m.role = 'admin'::text))))))","schema":"public","command":"UPDATE","permissive":"PERMISSIVE"},{"name":"snote_brand_media_delete_guard","check":null,"roles":["authenticated"],"table":"zc_media","using":"((group_name <> ALL (ARRAY['companyStamp'::text, 'companyLogo'::text])) OR (EXISTS ( SELECT 1\n   FROM zc_members member\n  WHERE ((member.user_id = ( SELECT auth.uid() AS uid)) AND (member.company_id = zc_media.company_id) AND (member.active IS TRUE) AND (member.role = 'admin'::text)))))","schema":"public","command":"DELETE","permissive":"RESTRICTIVE"},{"name":"snote_brand_media_insert_guard","check":"((group_name <> ALL (ARRAY['companyStamp'::text, 'companyLogo'::text])) OR ((owner_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1\n   FROM zc_members member\n  WHERE ((member.user_id = ( SELECT auth.uid() AS uid)) AND (member.company_id = zc_media.company_id) AND (member.active IS TRUE) AND (member.role = 'admin'::text))))))","roles":["authenticated"],"table":"zc_media","using":null,"schema":"public","command":"INSERT","permissive":"RESTRICTIVE"},{"name":"zc_media_delete","check":null,"roles":["authenticated"],"table":"zc_media","using":"(zc_is_member(company_id) AND ((owner_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM zc_members m\n  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.company_id = zc_media.company_id) AND m.active AND (m.role = 'admin'::text))))))","schema":"public","command":"DELETE","permissive":"PERMISSIVE"},{"name":"zc_media_insert","check":"(zc_is_member(company_id) AND (owner_id = ( SELECT auth.uid() AS uid)))","roles":["authenticated"],"table":"zc_media","using":null,"schema":"public","command":"INSERT","permissive":"PERMISSIVE"},{"name":"zc_media_read","check":null,"roles":["authenticated"],"table":"zc_media","using":"zc_is_member(company_id)","schema":"public","command":"SELECT","permissive":"PERMISSIVE"}],"functions":[{"name":"on_customer_delete","schema":"zc_private","definition":"CREATE OR REPLACE FUNCTION zc_private.on_customer_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nbegin\r\n delete from zc_private.rrn_secrets where company_id=old.company_id and owner_id=old.owner_id and car_id=old.car_id;\r\n insert into public.zc_audit(company_id,actor_id,entity,item_key,action)\r\n values(old.company_id,auth.uid(),'customer',old.car_id,'delete');\r\n return old;\r\nEND;\r\n$function$\n"},{"name":"zc_can_write","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.zc_can_write(c uuid, d text, o uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n select exists(select 1 from public.zc_members m where m.user_id=(select auth.uid()) and m.company_id=c and m.active\r\n   and (m.role='admin' or (d in ('cars','covers') and o=(select auth.uid()) and m.role='dealer')\r\n      or (d in ('finance','finance_limits','prestock','monthly','categories') and m.role='accountant')))\r\n$function$\n"},{"name":"zc_is_member","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.zc_is_member(c uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n select exists(select 1 from public.zc_members where user_id=(select auth.uid()) and company_id=c and active)\r\n$function$\n"},{"name":"zc_read_rrn","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.zc_read_rrn(p_company uuid, p_owner uuid, p_car_id text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare v_key text; v_cipher bytea;\r\nbegin\r\n if not public.zc_is_member(p_company) or p_owner<>auth.uid() then raise exception '주민번호 조회 권한 없음';end if;\r\n if not exists(select 1 from public.zc_companies where id=p_company and rrn_enabled) then return null;end if;\r\n select cipher into v_cipher from zc_private.rrn_secrets where company_id=p_company and owner_id=p_owner and car_id=p_car_id and expires_at>now();\r\n if v_cipher is null then return null;end if;\r\n select secret into v_key from zc_private.rrn_keys where company_id=p_company;\r\n insert into public.zc_audit(company_id,actor_id,entity,item_key,action) values(p_company,auth.uid(),'rrn',p_car_id,'read');\r\n return extensions.pgp_sym_decrypt(v_cipher,v_key);\r\nEND;\r\n$function$\n"},{"name":"zc_save_rrn","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.zc_save_rrn(p_company uuid, p_owner uuid, p_car_id text, p_rrn text)\n RETURNS timestamp with time zone\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare v_key text;v_end timestamptz;\r\nbegin\r\n if not public.zc_is_member(p_company) or p_owner<>auth.uid() then raise exception '접근 불가';end if;\r\n if not exists(select 1 from public.zc_companies where id=p_company and rrn_enabled) then raise exception '회사 주민번호 보관이 비활성화되어 있습니다. 법적 근거 검토가 선행되어야 합니다';end if;\r\n if p_rrn !~ '^[0-9]{13}$' then raise exception '주민번호 13자리 확인';end if;\r\n if not exists(select 1 from public.zc_customers where company_id=p_company and owner_id=p_owner and car_id=p_car_id) then raise exception '고객정보 먼저 저장';end if;\r\n select secret into v_key from zc_private.rrn_keys where company_id=p_company;\r\n v_end=now()+interval '30 days';\r\n insert into zc_private.rrn_secrets(company_id,owner_id,car_id,cipher,expires_at)\r\n values(p_company,p_owner,p_car_id,extensions.pgp_sym_encrypt(p_rrn,v_key,'cipher-algo=aes256'),v_end)\r\n on conflict(company_id,owner_id,car_id) do update set cipher=excluded.cipher, expires_at=excluded.expires_at,created_at=now();\r\n update public.zc_customers set has_rrn=true where company_id=p_company and owner_id=p_owner and car_id=p_car_id;\r\n insert into public.zc_audit(company_id,actor_id,entity,item_key,action) values(p_company,auth.uid(),'rrn',p_car_id,'save');\r\n return v_end;\r\nEND;\r\n$function$\n"},{"name":"zc_write_dataset","schema":"public","definition":"CREATE OR REPLACE FUNCTION public.zc_write_dataset(p_company uuid, p_dataset text, p_owner uuid, p_expected integer, p_payload jsonb)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare v_rev integer;\r\nbegin\r\n if p_dataset not in ('cars','covers','finance','finance_limits','prestock','monthly','categories') then raise exception '허용되지 않는 장부';end if;\r\n if p_dataset in ('cars','covers') and p_owner='00000000-0000-0000-0000-000000000000'::uuid then raise exception '차량 주인이 필요합니다';end if;\r\n if p_dataset not in ('cars','covers') and p_owner<>'00000000-0000-0000-0000-000000000000'::uuid then raise exception '공유장부 소유자 오류';end if;\r\n if not public.zc_can_write(p_company,p_dataset,p_owner) then raise exception '저장 권한이 없습니다';end if;\r\n if octet_length(p_payload::text)>3000000 then raise exception '장부 크기 제한 초과';end if;\r\n if p_expected=0 then\r\n   insert into public.zc_datasets(company_id,dataset,owner_id,payload,revision,updated_by)\r\n     values(p_company,p_dataset,p_owner,p_payload,1,auth.uid()) on conflict do nothing returning revision into v_rev;\r\n else\r\n   update public.zc_datasets set payload=p_payload,revision=revision+1,updated_by=auth.uid(),updated_at=now()\r\n     where company_id=p_company and dataset=p_dataset and owner_id=p_owner and revision=p_expected returning revision into v_rev;\r\n end if;\r\n if v_rev is null then raise exception 'CONFLICT: 다른 화면에서 먼저 저장했습니다. 서버 새로고침 후 재작업하세요';end if;\r\n insert into public.zc_audit(company_id,actor_id,entity,item_key,action) values(p_company,auth.uid(),'dataset',p_dataset||':'||p_owner::text,'write');\r\n return v_rev;\r\nEND;\r\n$function$\n"}]};
const MORE_BASELINE={"jobs":[{"name":"snote-customer-intake-daily-purge","active":true,"command":"select public.snote_intake_purge();"}],"triggers":[{"name":"protect_objects_delete","table":"storage.objects","function":"CREATE OR REPLACE FUNCTION storage.protect_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    -- Check if storage.allow_delete_query is set to 'true'\n    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN\n        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'\n            USING HINT = 'This prevents accidental data loss from orphaned objects.',\n                  ERRCODE = '42501';\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n","definition":"CREATE TRIGGER protect_objects_delete BEFORE DELETE ON storage.objects FOR EACH STATEMENT EXECUTE FUNCTION storage.protect_delete()"},{"name":"update_objects_updated_at","table":"storage.objects","function":"CREATE OR REPLACE FUNCTION storage.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = now();\n    RETURN NEW; \nEND;\n$function$\n","definition":"CREATE TRIGGER update_objects_updated_at BEFORE UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION storage.update_updated_at_column()"},{"name":"snote_shared_vehicle_change","table":"zc_datasets","function":"CREATE OR REPLACE FUNCTION snote_private.record_shared_vehicle_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_old jsonb;v_new jsonb;v_changes jsonb;v_actor uuid:=auth.uid();v_key text;v_before numeric;v_after numeric;v_factor numeric;\n v_fields text[]:=array['model','plate','make','year','vin','mileage','color','purchaseAt','buy','sell','status','inventoryLoan','inventoryLender'];\nbegin\n if new.dataset<>'cars' or v_actor is null or new.updated_by is distinct from v_actor or new.payload is not distinct from old.payload or jsonb_typeof(new.payload)<>'array' or jsonb_typeof(old.payload)<>'array' then return new;end if;\n if not exists(select 1 from snote_private.vehicle_shares where company_id=new.company_id and owner_id=new.owner_id) then return new;end if;\n for v_new in select c from jsonb_array_elements(new.payload)c where exists(select 1 from snote_private.vehicle_shares s where s.company_id=new.company_id and s.owner_id=new.owner_id and s.car_id=c->>'id') loop\n  select c into v_old from jsonb_array_elements(old.payload)c where c->>'id'=v_new->>'id';if v_old is null then continue;end if;\n  v_changes:='[]';\n  foreach v_key in array v_fields loop\n   if v_old->v_key is distinct from v_new->v_key then v_changes:=v_changes||jsonb_build_array(jsonb_build_object('field',v_key,'before',v_old->v_key,'after',v_new->v_key));end if;\n  end loop;\n\n  -- Compare the new optional cost in won; preserve the outgoing notification's unit.\n  v_before:=case when jsonb_typeof(v_old#>'{costs,performanceInspection}')='number' then (v_old#>>'{costs,performanceInspection}')::numeric else 0 end;\n  v_after:=case when jsonb_typeof(v_new#>'{costs,performanceInspection}')='number' then (v_new#>>'{costs,performanceInspection}')::numeric else 0 end;\n  if coalesce(v_old->>'moneyUnit','legacy')<>'KRW' then v_before:=v_before*10000;end if;\n  if coalesce(v_new->>'moneyUnit','legacy')<>'KRW' then v_after:=v_after*10000;end if;\n  if v_before is distinct from v_after then\n   v_factor:=case when v_new->>'moneyUnit'='KRW' then 1 else 10000 end;\n   v_changes:=v_changes||jsonb_build_array(jsonb_build_object('field','costs.performanceInspection','before',v_before/v_factor,'after',v_after/v_factor));\n  end if;\n  if jsonb_array_length(v_changes)=0 then continue;end if;\n  insert into snote_private.vehicle_notifications(company_id,owner_id,car_id,recipient_id,actor_id,car_label,changes,money_unit)\n  select new.company_id,new.owner_id,v_new->>'id',r.id,v_actor,left(concat_ws(' · ',v_new->>'model',v_new->>'plate'),300),v_changes,coalesce(v_new->>'moneyUnit','legacy') from (\n   select new.owner_id id union select recipient_id from snote_private.vehicle_shares where company_id=new.company_id and owner_id=new.owner_id and car_id=v_new->>'id'\n  )r join public.zc_members m on m.user_id=r.id and m.active and m.role in ('dealer','admin') where r.id<>v_actor;\n end loop;return new;\nend;$function$\n","definition":"CREATE TRIGGER snote_shared_vehicle_change AFTER UPDATE ON public.zc_datasets FOR EACH ROW EXECUTE FUNCTION snote_private.record_shared_vehicle_change()"},{"name":"zc_customer_delete_purge","table":"zc_customers","function":"CREATE OR REPLACE FUNCTION zc_private.on_customer_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\nbegin\r\n delete from zc_private.rrn_secrets where company_id=old.company_id and owner_id=old.owner_id and car_id=old.car_id;\r\n insert into public.zc_audit(company_id,actor_id,entity,item_key,action)\r\n values(old.company_id,auth.uid(),'customer',old.car_id,'delete');\r\n return old;\r\nEND;\r\n$function$\n","definition":"CREATE TRIGGER zc_customer_delete_purge AFTER DELETE ON public.zc_customers FOR EACH ROW EXECUTE FUNCTION zc_private.on_customer_delete()"}],"intake_functions":[{"name":"lock_actor_car","definition":"CREATE OR REPLACE FUNCTION snote_intake_private.lock_actor_car(p_owner uuid, p_company uuid, p_car_id text, p_allow_sold boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  v_payload jsonb;\r\n  v_car jsonb;\r\n  v_count integer;\r\n  v_sell numeric;\r\nbegin\r\n  if p_owner is null or p_company is null or p_car_id is null then return null; end if;\r\n  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('snote-intake:actor:' || p_owner::text, 0));\r\n  perform 1 from public.zc_members as member\r\n    where member.user_id = p_owner and member.company_id = p_company\r\n      and member.active is true and member.role in ('dealer', 'admin')\r\n    for share;\r\n  if not found then return null; end if;\r\n  select dataset.payload into v_payload\r\n    from public.zc_datasets as dataset\r\n    where dataset.company_id = p_company and dataset.owner_id = p_owner and dataset.dataset = 'cars'\r\n    for share;\r\n  if not found or pg_catalog.jsonb_typeof(v_payload) is distinct from 'array' then return null; end if;\r\n  select pg_catalog.count(*) into v_count\r\n    from pg_catalog.jsonb_array_elements(v_payload) as item(value)\r\n    where pg_catalog.jsonb_typeof(item.value) = 'object' and item.value ->> 'id' = p_car_id;\r\n  if v_count <> 1 then return null; end if;\r\n  select item.value into v_car from pg_catalog.jsonb_array_elements(v_payload) as item(value)\r\n    where item.value ->> 'id' = p_car_id;\r\n  if not p_allow_sold and coalesce(v_car ->> 'status', '') not in ('판매중', '매입진행', '수리중') then return null; end if;\r\n  if pg_catalog.jsonb_typeof(v_car -> 'model') is distinct from 'string'\r\n    or pg_catalog.char_length(pg_catalog.btrim(v_car ->> 'model')) not between 1 and 200 then return null; end if;\r\n  if pg_catalog.jsonb_typeof(v_car -> 'sell') in ('number', 'string')\r\n    and (v_car ->> 'sell') ~ '^[0-9]{1,9}([.][0-9]{1,4})?$' then\r\n    v_sell := (v_car ->> 'sell')::numeric;\r\n  end if;\r\n  return pg_catalog.jsonb_build_object(\r\n    'model', pg_catalog.btrim(v_car ->> 'model'),\r\n    'plate', case when pg_catalog.jsonb_typeof(v_car -> 'plate') = 'string' then pg_catalog.left(v_car ->> 'plate', 30) else '' end,\r\n    'year', case when pg_catalog.jsonb_typeof(v_car -> 'year') in ('number', 'string') and (v_car ->> 'year') ~ '^[0-9]{4}$' then v_car -> 'year' else 'null'::jsonb end,\r\n    'km', case when pg_catalog.jsonb_typeof(v_car -> 'km') in ('number', 'string') then pg_catalog.left(v_car ->> 'km', 30) else '' end,\r\n    'color', case when pg_catalog.jsonb_typeof(v_car -> 'color') = 'string' then pg_catalog.left(v_car ->> 'color', 50) else '' end,\r\n    'sell', v_sell\r\n  );\r\nend;\r\n$function$\n"},{"name":"lock_link","definition":"CREATE OR REPLACE FUNCTION snote_intake_private.lock_link(p_token_hash text)\n RETURNS snote_customer_intake\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  v_row public.snote_customer_intake%rowtype;\r\nbegin\r\n  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then return null; end if;\r\n  select intake.* into v_row from public.snote_customer_intake as intake where intake.token_hash = p_token_hash;\r\n  if not found then return null; end if;\r\n  if snote_intake_private.lock_actor_car(v_row.owner_id, v_row.company_id, v_row.car_id) is null then return null; end if;\r\n  select intake.* into v_row from public.snote_customer_intake as intake\r\n    where intake.id = v_row.id and intake.token_hash = p_token_hash for update;\r\n  if not found then return null; end if;\r\n  return v_row;\r\nend;\r\n$function$\n"}]};
const COMPANY='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',FOREIGN='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
const OWNER='11111111-1111-4111-8111-111111111111',UPLOADER='22222222-2222-4222-8222-222222222222',ADMIN='33333333-3333-4333-8333-333333333333',OUTSIDER='44444444-4444-4444-8444-444444444444',ACCOUNTANT='55555555-5555-4555-8555-555555555555',INACTIVE='66666666-6666-4666-8666-666666666666';
const ZERO='00000000-0000-0000-0000-000000000000';
const quote=id=>'"'+String(id).replaceAll('"','""')+'"';
